{
  "a_sentences": [
    {
      "a_text": "Streitig ist, ob die Vorinstanz Bundesrecht verletzte, indem sie die von der IV-Stelle am 9. Oktober 2023 verfügte Verneinung eines Rentenanspruchs bestätigte.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Für eine anspruchsrelevante Veränderung nach Art. 17 Abs. 1 ATSG genügt weder eine ungleich attestierte Arbeitsunfähigkeit noch eine abweichende diagnostische Einordnung; entscheidend ist vielmehr eine erheblich veränderte Befundlage.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Liegt ein Revisionsgrund vor, ist der Rentenanspruch umfassend und ohne Bindung an frühere Beurteilungen neu zu prüfen.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Zeitliche Vergleichsbasis für die Prüfung einer anspruchserheblichen Änderung bilden die Verfügungen vom 23. Oktober 2014 und 9. Oktober 2023.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Ein Vergleich des Gesundheitszustands der Versicherten im Zeitpunkt der letztmaligen Rentenprüfung im Jahr 2014 und der Verfügung vom 9. Oktober 2023 zeigt keine erhebliche Veränderung.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die Vorinstanz durfte auf das psychiatrische Gutachten abstellen.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Damit dringt die Versicherte nicht durch.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Zusammenfassend verletzt das angefochtene Urteil weder den Untersuchungsgrundsatz noch Art. 17 ATSG noch sonstwie Bundesrecht.",
      "b_propositions": ["P8"]
    }
  ]
}
